class _STR_LIST():
	def __init__(self, cympyObject, list_path):
		self._cympyObject = cympyObject
		self._list_path = list_path

	def Add(self, val):
		self._cympyObject.Execute(f'{self._list_path}.Add({val})')

	def GetCount(self):
		return int(self._cympyObject.GetValue(f'{self._list_path}.GetCount()'))

	def Clear(self):
		self._cympyObject.Execute(f'{self._list_path}.Clear()')

	def RemoveAt(self, index):
		self._cympyObject.Execute(f'{self._list_path}.RemoveAt({index})')

	def GetValues(self):
		length = int(self.GetCount())
		for i in range(length):
			yield self._cympyObject.GetValue(f'{self._list_path}[{i}]')

	def GetValueAt(self, index):
		return self._cympyObject.GetValue(f'{self._list_path}[{index}]')

