class _CYME_LIST():
	def __init__(self, cymeObj, list_path):
		self._cymeObj = cymeObj
		self._list_path = list_path

	def Add(self, *vals):
		self._cymeObj.Execute(f'{self._list_path}.Add({", ".join(vals)})')

	def GetCount(self):
		return int(self._cymeObj.GetValue(f'{self._list_path}.GetCount()'))

	def Clear(self):
		self._cymeObj.Execute(f'{self._list_path}.Clear()')

	def RemoveAt(self, index):
		self._cymeObj.Execute(f'{self._list_path}.RemoveAt({index})')

class _READ_ONLY_MEMBERS():
    def __setattr__(self, name, value):
        if name in self.__dict__:
            raise ValueError(f"Cannot modify attribute: {name}")
        else:
            object.__setattr__(self, name, value)

