class _SVCGenerationModel_cymeList(_CYME_LIST): # OBJ_LIST_GENERATOR
    def __init__(self, cympyObject, path):
        _CYME_LIST.__init__(self, cympyObject, path)
        self._cympyObject = cympyObject

    def GetValues(self):
        length = int(self.GetCount())
        for i in range(length):
            yield _SVCGenerationModel(self._cympyObject, f'{self._list_path}[{i}]')

    def GetValueAt(self, index):
        length = int(self.GetCount())
        if length > index:
            return _SVCGenerationModel(self._cympyObject, f'{self._list_path}[{index}]')
        else:
            raise ValueError(f'Index out of bound, index asked for: {index}, lenght of the list: {length}')

    def GetValueFor(self, criteria):
        for x in self.GetValues():
            if criteria(x):
                return x


